import openpyxl
from collections import defaultdict
from datetime import datetime
wb = openpyxl.load_workbook("./testbed/data/order_summary.xlsx")
ws = wb.active
headers = [cell.value for cell in ws[1]]
rows = []
for row in ws.iter_rows(min_row=2, values_only=True):
    rows.append(dict(zip(headers, row)))
total = len(rows)
print("TOTAL ORDERS:", total)
print()
amount_cols = [h for h in headers if h and any(k in str(h).lower() for k in ["amount","total","price","revenue","sales","cost","value","quantity","qty"])]
date_cols = [h for h in headers if h and any(k in str(h).lower() for k in ["date","time","created","ordered"])]
status_cols = [h for h in headers if h and any(k in str(h).lower() for k in ["status","state"])]
cat_cols = [h for h in headers if h and any(k in str(h).lower() for k in ["category","type","product","item","region","channel","customer","name"])]
for ac in amount_cols:
    nums = []
    for r in rows:
        try:
            nums.append(float(r[ac]))
        except Exception:
            pass
    if nums:
        print("=== " + str(ac) + " ===")
        print("  Sum:", "{:,.2f}".format(sum(nums)))
        print("  Avg:", "{:,.2f}".format(sum(nums)/len(nums)))
        print("  Min:", "{:,.2f}".format(min(nums)))
        print("  Max:", "{:,.2f}".format(max(nums)))
        print("  Count:", len(nums))
        print()
for sc in status_cols:
    counts = defaultdict(int)
    for r in rows:
        counts[r[sc]] += 1
    print("=== " + str(sc) + " Breakdown ===")
    for k, v in sorted(counts.items(), key=lambda x: -x[1]):
        pct = "{:.1f}".format(v/total*100)
        print("  " + str(k) + ": " + str(v) + " (" + pct + "%)")
    print()
for cc in cat_cols:
    counts = defaultdict(int)
    sums = defaultdict(float)
    for r in rows:
        key = r[cc]
        counts[key] += 1
        for ac in amount_cols:
            try:
                sums[key] += float(r[ac])
            except Exception:
                pass
    print("=== " + str(cc) + " Breakdown ===")
    for k, v in sorted(counts.items(), key=lambda x: -x[1]):
        pct = "{:.1f}".format(v/total*100)
        line = "  " + str(k) + ": " + str(v) + " orders (" + pct + "%)"
        if sums.get(k):
            line += " | Total: " + "{:,.2f}".format(sums[k])
        print(line)
    print()
for dc in date_cols:
    dates = []
    date_rows = []
    for r in rows:
        v = r[dc]
        if v is None:
            continue
        if isinstance(v, datetime):
            dates.append(v)
            date_rows.append(r)
        else:
            for fmt in ["%Y-%m-%d","%m/%d/%Y","%d/%m/%Y","%Y-%m-%d %H:%M:%S"]:
                try:
                    dates.append(datetime.strptime(str(v), fmt))
                    date_rows.append(r)
                    break
                except Exception:
                    pass
    if dates:
        print("=== " + str(dc) + " Analysis ===")
        print("  Earliest:", min(dates).strftime("%Y-%m-%d"))
        print("  Latest:", max(dates).strftime("%Y-%m-%d"))
        monthly = defaultdict(int)
        monthly_amt = defaultdict(float)
        for d, r in zip(dates, date_rows):
            mk = d.strftime("%Y-%m")
            monthly[mk] += 1
            for ac in amount_cols:
                try:
                    monthly_amt[mk] += float(r[ac])
                except Exception:
                    pass
        print("  Monthly Trends:")
        for m in sorted(monthly.keys()):
            line = "    " + m + ": " + str(monthly[m]) + " orders"
            if monthly_amt[m]:
                line += " | Amount: " + "{:,.2f}".format(monthly_amt[m])
            print(line)
        print()
print("=== ANALYSIS COMPLETE ===")

